def test_intent_router_extracts_intents_and_tools():
    text = dedent('''
    enum UserIntent {
      case localSearch
      case webLookup
    }
    struct IntentRouter {
      func tools(for intent: UserIntent) -> [String] {
        switch intent {
        case .localSearch: return ["maps.search"]
        case .webLookup: return ["web.search"]
        }
      }
    }
